  const ancestors: unknown[] = [];

  // MLflow-specific replacer that handles functions, undefined, errors, and circular refs.
  function mlflowReplacer(this: any, _key: string, val: any): any {
    if (typeof val === 'function') {
      return '[Function]';
    }
    if (val === undefined) {
      return '[Undefined]';
    }
    if (val instanceof Error) {
