      // `this` is the holder object; drop any ancestors that are no longer part of
      // the current path before checking for a cycle.
      while (ancestors.length > 0 && ancestors[ancestors.length - 1] !== this) {
        ancestors.pop();
      }
      if (ancestors.includes(val)) {
        return '[Circular]';
      }
      ancestors.push(val);
    }

    return val;
  }

  return JSON.stringify(value, mlflowReplacer);
